+  color: var(--text-muted);
+}
+
+.results {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--r-lg);
+  padding: var(--space-4);
+  box-shadow: var(--shadow-sm);
+}
+
+.results-head {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.results-title {
+  font-size: 20px;
+}
+
+.results-meta {
+  margin: 0;
+  color: var(--text-muted);
+  font-weight: 600;
+}
+
+.results-table {
+  margin-top: var(--space-3);
+  overflow: auto;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
+}
+
+table {
+  width: 100%;
+  border-collapse: collapse;
+  min-width: 720px;
+  background: var(--surface);
+}
+
+th, td {
+  padding: 12px 12px;
+  text-align: left;
+  border-bottom: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
+  vertical-align: top;
+}
+
+th { font-weight: 900; background: color-mix(in oklch, var(--fp-green) 6%, var(--surface)); }
+td { color: var(--text); }
+
+.newsletter {
+  display: grid;
+  gap: var(--space-3);
+  align-items: center;
+  padding: var(--space-5);
+  border-radius: var(--r-lg);
+  background:
+    radial-gradient(900px 400px at 10% 10%, color-mix(in oklch, var(--fp-yellow) 30%, transparent), transparent 65%),
+    radial-gradient(900px 420px at 70% 50%, color-mix(in oklch, var(--fp-green) 12%, transparent), transparent 70%),
+    linear-gradient(180deg, var(--surface), color-mix(in oklch, var(--fp-cream) 70%, var(--surface)));
+  border: 1px solid var(--border);
+  box-shadow: var(--shadow-md);
+}
+
+.newsletter-form {
+  display: grid;
+  gap: 10px;
+}
+
+.form-note {
+  margin: 0;
+  color: var(--text-muted);
+  font-weight: 600;
+}
+
+.footer {
+  padding: var(--space-7) 0 var(--space-5);
+  background: color-mix(in oklch, var(--fp-cream) 80%, var(--surface));
+  border-top: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
+}
+
+.footer-grid {
+  display: grid;
+  gap: var(--space-5);
+}
+
+.brand--footer .brand-name { color: var(--text); }
+
+.footer-note {
+  margin: 12px 0 0;
+  color: var(--text-muted);
+  line-height: 1.55;
+}
+
+.footer-cols {
+  display: grid;
+  gap: var(--space-4);
+}
+
+.footer-col h3 {
+  font-size: 16px;
+  font-weight: 900;
+  margin-bottom: 10px;
+}
+
+.footer-col ul {
+  list-style: none;
+  padding: 0;
+  margin: 0;
+  display: grid;
+  gap: 8px;
+}
+
+.footer-col a {
+  color: var(--text-muted);
+  font-weight: 700;
+}
+
+.footer-col a:hover { color: var(--text); }
+
+.footer-bottom {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 10px;
+  padding-top: var(--space-3);
+  border-top: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
+  color: var(--text-muted);
+  font-weight: 700;
+}
+
+.to-top {
+  padding: 10px 12px;
+  border-radius: 999px;
+  background: color-mix(in oklch, var(--fp-green) 8%, var(--surface));
+  border: 1px solid color-mix(in oklch, var(--fp-green) 15%, var(--border));
+}
+
+.to-top:hover { background: color-mix(in oklch, var(--fp-green) 12%, var(--surface)); }
+
+@media (min-width: 640px) {
+  .container { padding: 0 var(--space-4); }
+  .nav-panel {
+    position: static;
+    display: flex;
+    gap: 6px;
+    padding: 0;
+    background: transparent;
+    border: 0;
+    box-shadow: none;
+    min-width: 0;
+  }
+  .nav-toggle { display: none; }
+  .hero-grid { grid-template-columns: 1.1fr 0.9fr; }
+  .seasonal-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .category-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .locator-form { grid-template-columns: 1fr auto; align-items: center; }
+  .field-help { grid-column: 1 / -1; }
+  .newsletter { grid-template-columns: 1.2fr 0.8fr; }
+  .newsletter-form { grid-template-columns: 1fr auto; align-items: center; }
+  .form-note { grid-column: 1 / -1; }
+}
+
+@media (min-width: 1024px) {
+  .seasonal-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
+  .highlights { grid-template-columns: repeat(4, minmax(0, 1fr)); }
+  .category-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
+  .footer-cols { grid-template-columns: repeat(4, minmax(0, 1fr)); }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  html { scroll-behavior: auto; }
+  .btn, .icon-btn, .product-card, .category-card { transition: none; }
+  .carousel-track { scroll-behavior: auto; }
+}
+
*** End Patch
PATCH"}

